# bash completion for nightshift — generated by `nightshift completion bash`
_nightshift() {
    local cur words cword reply i
    if declare -F _get_comp_words_by_ref >/dev/null; then
        _get_comp_words_by_ref -n =: cur words cword
    else
        # Rejoin COMP_LINE up to the cursor, splitting only on unquoted
        # whitespace, so ':' and '=' stay inside a word.
        local line=${COMP_LINE:0:COMP_POINT} ch q="" w="" have=0 esc=0
        words=()
        for ((i = 0; i < ${#line}; i++)); do
            ch=${line:i:1}
            if ((esc)); then
                w+=$ch; esc=0
            elif [[ $ch == '\' && $q != "'" ]]; then
                w+=$ch; esc=1; have=1
            elif [[ -n $q ]]; then
                w+=$ch; [[ $ch == "$q" ]] && q=""
            elif [[ $ch == "'" || $ch == '"' ]]; then
                w+=$ch; q=$ch; have=1
            elif [[ $ch == [[:space:]] ]]; then
                if ((have)); then words+=("$w"); w=""; have=0; fi
            else
                w+=$ch; have=1
            fi
        done
        words+=("$w")
        cword=$((${#words[@]} - 1))
        cur=${words[cword]}
    fi
    reply=$(__NIGHTSHIFT_BIN__ __complete "${words[@]:1:cword-1}" "$cur" 2>/dev/null)
    # Readline replaces only the text after the last COMP_WORDBREAKS
    # character, so drop that leading part of $cur from each candidate.
    local t=$cur c pre
    for c in = :; do
        [[ $COMP_WORDBREAKS == *"$c"* ]] && t=${t##*"$c"}
    done
    pre=${cur%"$t"}
    COMPREPLY=()
    if [[ $reply == __dirs__ ]]; then
        compopt -o filenames 2>/dev/null
        mapfile -t COMPREPLY < <(compgen -d -- "$t")
    elif [[ -n $reply ]]; then
        mapfile -t COMPREPLY <<<"$reply"
        for i in "${!COMPREPLY[@]}"; do
            COMPREPLY[i]=${COMPREPLY[i]#"$pre"}
        done
        if declare -F __ltrim_colon_completions >/dev/null; then
            __ltrim_colon_completions "$cur"
        fi
    fi
}
complete -F _nightshift nightshift
